@props([ 'paginator' => null, ]) @if($paginator && $paginator->hasPages()) <div {{ $attributes->merge(['class' => 'ui-pagination']) }}><div class="ui-pagination-info"> Menampilkan <strong>{{ $paginator->firstItem() }}</strong> sampai <strong>{{ $paginator->lastItem() }}</strong> dari <strong>{{ $paginator->total() }}</strong> hasil </div><div class="ui-pagination-pages"> @if ($paginator->onFirstPage()) <span class="ui-page-item is-disabled"><i class="fa-solid fa-chevron-left"></i></span> @else <a href="{{ $paginator->previousPageUrl() }}" class="ui-page-item" rel="prev"><i class="fa-solid fa-chevron-left"></i></a> @endif @foreach ($paginator->links()->elements as $element) @if (is_string($element)) <span class="ui-page-item is-disabled">{{ $element }}</span> @endif @if (is_array($element)) @foreach ($element as $page => $url) @if ($page == $paginator->currentPage()) <span class="ui-page-item is-active">{{ $page }}</span> @else <a href="{{ $url }}" class="ui-page-item">{{ $page }}</a> @endif @endforeach @endif @endforeach @if ($paginator->hasMorePages()) <a href="{{ $paginator->nextPageUrl() }}" class="ui-page-item" rel="next"><i class="fa-solid fa-chevron-right"></i></a> @else <span class="ui-page-item is-disabled"><i class="fa-solid fa-chevron-right"></i></span> @endif </div></div> @elseif($slot->isNotEmpty()) <div {{ $attributes->merge(['class' => 'ui-pagination']) }}>{{ $slot }}</div> @endif